using ControlGastos.Core.Entities; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace ControlGastos.Infrastructure.Configurations;
public sealed class VinculacionTelegramConfiguration : IEntityTypeConfiguration<VinculacionTelegram> { public void Configure(EntityTypeBuilder<VinculacionTelegram> b) { b.ToTable("tbt_vinculacion_telegram", "finanzas"); b.HasKey(x=>x.IdVinculacion); b.Property(x=>x.IdVinculacion).HasColumnName("idd_vinculacion"); b.Property(x=>x.IdUsuario).HasColumnName("idd_usuario"); b.Property(x=>x.CodigoToken).HasColumnName("cod_token").HasMaxLength(100); b.Property(x=>x.FechaExpiracion).HasColumnName("fec_expiracion"); b.Property(x=>x.EstaUsado).HasColumnName("est_usado"); b.Property(x=>x.FechaRegistro).HasColumnName("fec_regis"); } }
